{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue party gathers at the edge of the ruined city.",
      "visual_description": "A cracked overlook above a shattered royal skyline, broken spires under a bruised sky, ink-stained map unrolled on a stone.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "Mara plots the route through the dead capital.",
      "visual_description": "Close on a hand-drawn map with red ink marking the castle gates, cursed towers, and a far bridge; a brass compass spins beside it.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The lamp warns of the first temptation.",
      "visual_description": "Oracle lamp's single flame-eye flares as it floats before a towering iron castle gate hung with tattered royal banners.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox slips through a broken window to scout.",
      "visual_description": "A small clockwork fox squeezing through jagged stained glass, key-wind tail glinting, blue glass eyes scanning a courtyard.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The Glass Diver emerges from a tall mirror.",
      "visual_description": "A figure in a clear diving helmet steps out of a cracked ballroom mirror, coat shimmering with reflected city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "They find the sleeping official slumped at his post.",
      "visual_description": "A dusty toll booth where a uniformed man snores on a ledger pillow, stamped papers fluttering on his sleeves.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The lamp refuses to enter the cursed tower.",
      "visual_description": "A leaning black tower wreathed in green smoke; the oracle lamp shrinks back, flame-eye narrowed, casting a long warning shadow.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Armored patrols march along the boulevard.",
      "visual_description": "From behind a toppled fountain, the party watches faceless armored figures in lockstep, polearms catching cold moonlight.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox lures the patrol away with a clattering ruse.",
      "visual_description": "The little fox scampers across cobblestones tossing tin cups; armored shapes turn and follow the noise down an alley.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a great winged beast ripple through empty streets.",
      "visual_description": "A huge clawed shadow sweeps across cracked plaza tiles while the party crouches under a fallen royal banner.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Frightened townsfolk peek from boarded windows.",
      "visual_description": "Narrow eyes glint between planks of shuttered houses; Mara raises a calm hand, compass on her belt catching lantern light.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "A sealed magic door blocks the inner keep.",
      "visual_description": "A circular door carved with rotating glyphs glows pale blue in a stone archway; runes drift slowly like fish in water.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The Glass Diver dives through the door's reflection.",
      "visual_description": "The diver plunges headfirst into the door's mirrored surface, coat rippling, helmet bubbles trailing into shimmering glyphs.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Inside, they find the captive bound in chains of light.",
      "visual_description": "A vaulted throne room where the sleeping official is tangled in glowing rope-like beams, ledger fallen open at his feet.",
      "characters": ["glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Mara cuts the binding light using compass and ink.",
      "visual_description": "Mara traces a sharp ink line across the air; the chains of light split like cut thread, scattering bright sparks across the marble.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Alarm horns sound; the patrols converge.",
      "visual_description": "Red banners ripple as armored shapes pour from side doors; the party flees down a colonnade, tin fox skittering ahead.",
guardian      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the long bridge over the chasm.",
      "visual_description": "A narrow stone bridge arching over a smoking gorge; the rescued official is half-carried, oracle lamp lighting the way forward.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, the ruined city burns behind them.",
      "visual_description": "Dawn over a misty hillside; the party looks back at distant fires while the tin fox's tail clicks down its last winding.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

